from pathlib import Path
import json, shutil, hashlib, datetime
R=Path(__file__).resolve().parents[2]; W=R/'work/movement-integration'; L=R/'outputs/d2-coop-lab'
A=W/'candidate-npc-combat-v1214cp'; P=W/'candidate-npc-combat-v1214co'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest().upper()
previous=json.loads((P/'identity.json').read_text(encoding='utf-8-sig'))
assert sha(R/'work/asset-game/dinput8.dll')==json.loads((W/'candidate-npc-combat-v1214cn'/'identity.json').read_text(encoding='utf-8-sig'))['dll']  # 1214co was archived without deployment; 1214cn is live
for tag in ('build','world-tests','action-tests','bank-tests','smoke','resume-tests','checkpoint-tests','pose-tests','arm-reach-tests','tables-tests','rebuild-tests'):
    t=(W/f'powervisuals-{tag}-v1214cp.log').read_text(encoding='utf-8-sig')
    assert t and not any(x in t for x in ('error C','error LNK','FAIL ','Traceback'))
A.mkdir(exist_ok=False); shutil.copytree(L/'src', A/'src')
shutil.copy2(L/'Send-D2Command.ps1', A/'Send-D2Command.ps1')
for name in ('dinput8.dll','d2_runtime_probe.exe','d2coop_setup.exe'):shutil.copy2(R/'work/build/Release'/name,A/name)
for name in ('Build-PowerVisuals-v1214cp.ps1','Deploy-PowerVisuals-v1214cp.ps1','stage_powervisuals_v1214cp.py'):shutil.copy2(W/name,A/name)
tables=R/'work/release/native-tables-v1/native-tables.bin'
for bank in previous['banks']:assert sha(R/bank['path'])==bank['sha256']
assert sha(tables)==previous['nativeTables']['sha256']
identity=dict(created=datetime.datetime.now().astimezone().isoformat(),dll=sha(A/'dinput8.dll'),probe=sha(A/'d2_runtime_probe.exe'),setup=sha(A/'d2coop_setup.exe'),previous=P.name,protocol=previous['protocol'],npcAttackPacketVersion=previous['npcAttackPacketVersion'],bankVersion=previous['bankVersion'],clips=previous['clips'],banks=previous['banks'],nativeTables=previous['nativeTables'],runtimeVerified=False,coinProtocol=previous['coinProtocol'],coinCatalogListProtocol=previous['coinCatalogListProtocol'],scope='1214cp (#104): 1214co plus the product-mode partner world visuals of Emily powers: the Doppelganger clone (serviceDoppelgangerVisual) and the networked Mesmerize spirit (serviceMesmerizeVisual) also run while the product controller holds an armed session (productSessionArmed), not only inside the isolated lab fixture; the spirit local experiment stays lab-only. Both remain cosmetic; NPC perception is stage 4. Includes 1214co (the damaging landing binds the body and both native arms). Otherwise 1214co.')
(A/'identity.json').write_text(json.dumps(identity,indent=2))
for name in ('dinput8.dll','d2_runtime_probe.exe'):shutil.copy2(A/name,L/'bin'/name)
print(json.dumps(identity))
